-- 1. Relational SQL: Normalized schema with JOIN
SELECT u.name, o.id, o.total, i.product_name
FROM users u
JOIN orders o ON u.id = o.user_id
JOIN order_items i ON o.id = i.order_id
WHERE u.id = $1;

// 2. DynamoDB / NoSQL: Single O(1) query on pre-joined partition key
const orderItem = await dynamoDb.get({
  TableName: "UserOrders",
  Key: {
    userId: "usr_102",      // Partition Key
    orderId: "ord_99824"     // Sort / Clustering Key
  }
});

// BAD: N+1 queries (1 query for orders + N queries for users)
const orders = await db.orders.findMany({ take: 50 });
for (const order of orders) {
  order.user = await db.users.findUnique({ where: { id: order.userId } }); // 50 round trips!
}

// GOOD: 2 queries total (Batch loading)
const ordersGood = await db.orders.findMany({ take: 50 });
const userIds = [...new Set(ordersGood.map(o => o.userId))];
const users = await db.users.findMany({ where: { id: { in: userIds } } }); // 1 round trip!
const userMap = new Map(users.map(u => [u.id, u]));
ordersGood.forEach(o => { o.user = userMap.get(o.userId); });

-- When author updates their name, synchronize denormalized comments asynchronously
CREATE OR REPLACE FUNCTION sync_user_name_to_comments()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.name <> OLD.name THEN
    -- Enqueue background task or update directly
    UPDATE comments 
    SET author_name = NEW.name 
    WHERE author_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Invariant: At least 1 doctor must remain on call for the shift.
-- Currently on call: Alice and Bob.

-- Transaction 1 (Alice):                 -- Transaction 2 (Bob):
BEGIN TRANSACTION ISOLATION LEVEL         BEGIN TRANSACTION ISOLATION LEVEL
REPEATABLE READ;                          REPEATABLE READ;

SELECT COUNT(*) FROM doctors             SELECT COUNT(*) FROM doctors
WHERE on_call = true;                    WHERE on_call = true;
-- Returns 2 (Alice can leave!)           -- Returns 2 (Bob can leave!)

UPDATE doctors SET on_call = false       UPDATE doctors SET on_call = false
WHERE name = 'Alice';                    WHERE name = 'Bob';

COMMIT;                                  COMMIT;
-- Both commit successfully under Snapshot Isolation! Zero doctors left on call (Write Skew)!

-- Transfer funds between two accounts safely
BEGIN TRANSACTION;

-- Ensure accounts are locked in consistent ascending order to eliminate deadlocks
SELECT id, balance FROM accounts 
WHERE id IN ('acc_01', 'acc_02') 
ORDER BY id ASC 
FOR UPDATE;

UPDATE accounts SET balance = balance - 100 WHERE id = 'acc_01';
UPDATE accounts SET balance = balance + 100 WHERE id = 'acc_02';

COMMIT;

export class SmartDatabaseRouter {
  constructor(private primaryDb: Database, private replicaPool: Database[]) {}

  async query(userId: string, sql: string, params: any[], isWrite: boolean) {
    if (isWrite) {
      // Record mutation timestamp in session cache
      await redis.set(`user:${userId}:last_write`, Date.now(), 'EX', 10);
      return this.primaryDb.query(sql, params);
    }

    // Check if user performed a write within the last 5 seconds
    const lastWrite = await redis.get(`user:${userId}:last_write`);
    if (lastWrite && Date.now() - Number(lastWrite) < 5000) {
      // Pin to primary to guarantee Read-Your-Own-Writes!
      return this.primaryDb.query(sql, params);
    }

    // Route normal reads randomly across healthy replica pool
    const replica = this.replicaPool[Math.floor(Math.random() * this.replicaPool.length)];
    return replica.query(sql, params);
  }
}

import crypto from 'node:crypto';

export class ShardRouter {
  constructor(private shards: string[]) {}

  getShardForUser(userId: string): string {
    // MD5 hash produces uniform 128-bit distribution
    const hash = crypto.createHash('md5').update(userId).digest('hex');
    const hashInt = parseInt(hash.substring(0, 8), 16);
    const shardIndex = hashInt % this.shards.length;
    return this.shards[shardIndex];
  }
}

